# Builds the model Polish chart of accounts (research proposal) as CSV, one Annex-7 tag per account.
import csv, re, sys
NOTES = sys.argv[1]; OUT = sys.argv[2]
# --- the tag dictionary, parsed from the filings note's Appendix A
tags = {}
inA = False
for line in open(NOTES + '/filings.md', encoding='utf-8'):
    if line.startswith('## Appendix A'): inA = True
    if not inA: continue
    m = re.match(r'\| `([A-Za-z0-9_]+)` \| (.+?) \|\s*$', line)
    if m: tags[m.group(1)] = m.group(2).strip()
annex7 = [t for t in tags if not t.startswith('PD')]
pdtags = [t for t in tags if t.startswith('PD')]
# --- the chart: code, name, nature, scope, S_12_1, S_12_3, F-01/GUS split, Rhea today, note
# nature: A aktywne, P pasywne, AP aktywno-pasywne, Kor korygujące, K kosztowe, Pr przychodowe, R rozliczeniowe, W wynikowe, PB pozabilansowe
R = []
def a(code, name, nature, scope, tag, pd='', f01='', rhea='', note=''):
    R.append(dict(code=code, name=name, nature=nature, scope=scope, s12_1=tag, s12_3=pd, f01=f01, rhea=rhea, note=note))
