# resolve synthetic tags (FAQ Q147)
kids={}
for r in R:
    parts=r['code'].split('-')
    for i in range(1,len(parts)): kids.setdefault('-'.join(parts[:i]),[]).append(r)
for r in R:
    if r['s12_1']==SYN:
        leaf={k['s12_1'] for k in kids.get(r['code'],[]) if k['s12_1']!=SYN and not any(x['code'].startswith(k['code']+'-') for x in R)}
        r['s12_1']=leaf.pop() if len(leaf)==1 else 'INNE'
# --- write, with parent and level, and check coverage
R.sort(key=lambda r: [int(x) if x.isdigit() else x for x in r['code'].split('-')])
codes={r['code'] for r in R}
for r in R:
    parts=r['code'].split('-'); r['level']=len(parts)
    r['parent']='-'.join(parts[:-1]) if len(parts)>1 else ''
    r['position']=tags.get(r['s12_1'],'') if r['s12_1']!='INNE' else ''
    r['pd_text']=tags.get(r['s12_3'],'')
bad=[r['code'] for r in R if r['parent'] and r['parent'] not in codes]
unknown=[ (r['code'],r['s12_1']) for r in R if r['s12_1'] not in tags]
unknown_pd=[ (r['code'],r['s12_3']) for r in R if r['s12_3'] and r['s12_3'] not in tags]
used={r['s12_1'] for r in R}|{r['s12_3'] for r in R}
missing=[t for t in tags if t not in used]
with open(OUT,'w',newline='',encoding='utf-8') as f:
    w=csv.DictWriter(f,fieldnames=['code','parent','level','name','nature','scope','s12_1','position','s12_3','pd_text','f01','rhea','note'])
    w.writeheader()
    for r in R: w.writerow({k:r[k] for k in w.fieldnames})
